// Alphabet-soup + question expansion for each seed (Google Autocomplete is unofficial: few queries, one every ~1.2 s)
const s = $('Set planner settings').first().json;
const out = [];
for (const j of $input.all().map(i => i.json)) {
  const seeds = String(j.seeds || '').split(/[\n,;]+/).map(x => x.trim().toLowerCase()).filter(Boolean).slice(0, 10);
  const max = Math.min(Number(j.max_queries || s.max_queries) || 80, 400);
  const per = Math.max(6, Math.floor(max / Math.max(seeds.length, 1)));
  for (const seed of seeds) {
    const qs = [seed, ...['how', 'what', 'why', 'best', 'is', 'can', 'which', 'where', 'when'].map(p => `${p} ${seed}`),
      `${seed} vs`, `${seed} for`, `${seed} cost`, `${seed} near me`, `${seed} without`, `${seed} or`,
      ...'abcdefghijklmnopqrstuvwxyz'.split('').map(c => `${seed} ${c}`)];
    for (const q of qs.slice(0, per)) out.push({ json: { project: j.project || s.default_project, seed, q, hl: j.hl || s.default_hl, gl: j.gl || s.default_gl } });
  }
}
return out;

// Parse suggestions, normalise, dedupe, and count how many queries surfaced each keyword.
// "hits" is a rough popularity signal, NOT search volume (Autocomplete gives no volumes).
const reqs = $('Plan autocomplete queries').all();
const STOP = new Set(['the', 'a', 'an', 'for', 'to', 'of', 'in', 'on', 'and', 'or', 'is', 'vs', 'with', 'near', 'me', 'my', 'how', 'what', 'why', 'best', 'can', 'which', 'where', 'when']);
const hint = k => /\b(buy|price|prices|cost|costs|cheap|deal|discount|coupon|hire|book|order|near me|for sale|quote|subscription)\b/.test(k) ? 'transactional'
  : /\b(best|top|vs|versus|review|reviews|compare|comparison|alternative|alternatives)\b/.test(k) ? 'commercial'
  : /^(how|what|why|when|where|which|who|is|can|does|do|should|are)\b/.test(k) ? 'informational' : 'mixed';
const prev = new Set();
const P = {};
// read the HTTP results by node name: in Pro, "Read previous keywords" sits between the HTTP node and this one
$('Get Google Autocomplete suggestions').all().forEach((item, i) => {
  const r = reqs[i].json;
  const p = P[r.project] = P[r.project] || { project: r.project, seeds: new Set(), kw: {}, queries: 0, failed: 0 };
  p.seeds.add(r.seed); p.queries++;
  if (/automated queries|unusual traffic|<title>Sorry/i.test(String(item.json.data || ''))) p.blocked = (p.blocked || 0) + 1;
  let arr = null;
  try { const d = typeof item.json.data === 'string' ? JSON.parse(item.json.data) : item.json; arr = Array.isArray(d) ? d[1] : d['1']; } catch (e) {}
  if (!Array.isArray(arr)) { p.failed++; return; }
  const sig = r.seed.split(' ').filter(w => w.length > 2 && !STOP.has(w));
  for (let k of [r.seed, ...arr]) {
    k = String(k).toLowerCase().replace(/\s+/g, ' ').trim();
    if (!k || k.length > 90 || (sig.length && !sig.some(w => k.includes(w.replace(/s$/, ''))))) continue;  // drifted suggestion
    const e = p.kw[k] = p.kw[k] || { keyword: k, seed: r.seed, hits: 0 };
    e.hits++;
  }
});
const s = $('Set planner settings').first().json;
const today = $now.toFormat('yyyy-MM-dd');
return Object.values(P).map(p => {
  const keywords = Object.values(p.kw).sort((a, b) => b.hits - a.hits || a.keyword.length - b.keyword.length)
    .slice(0, Number(s.max_keywords) || 200)
    .map((k, i) => ({ id: i + 1, ...k, keyword_key: `${p.project}|${k.keyword}`, intent_hint: hint(k.keyword),
      is_question: /^(how|what|why|when|where|which|who|is|can|does|do|should|are)\b/.test(k.keyword), words: k.keyword.split(' ').length,
      is_new: prev.size ? !prev.has(`${p.project}|${k.keyword}`) : false, last_seen: today }));
  return { json: { project: p.project, seeds: [...p.seeds].join(', '), queries: p.queries, failed_queries: p.failed, blocked_queries: p.blocked || 0,
    keyword_count: keywords.length, new_count: keywords.filter(k => k.is_new).length, keywords,
    keyword_list: keywords.map(k => `${k.id}. ${k.keyword} [${k.hits}]`).join('\n') } };
});

// Nothing to cluster: say why instead of calling Gemini with an empty list (nothing is written to the sheet)
const j = $json;
const why = j.blocked_queries ? `Google answered ${j.blocked_queries} of ${j.queries} Autocomplete calls with its "unusual traffic" page, so this server's IP is being rate-limited.`
  : j.failed_queries ? `${j.failed_queries} of ${j.queries} Google Autocomplete calls failed.` : `Google Autocomplete returned no suggestions that match your seeds.`;
const fix = j.failed_queries ? 'Try again in an hour, lower max_queries in Set planner settings, or run the workflow from another n8n host.' : 'Try broader or shorter seed keywords.';
const msg = `No keywords found for ${j.project ? j.project + ' (' + j.seeds + ')' : j.seeds}. ${why} ${fix} Nothing was written to your Google Sheet.`;
return [{ json: { ...j, message: msg, subject: `Keyword planner: no keywords for ${j.project || j.seeds}`, html: `<h2>No keywords found</h2><p>${msg}</p>` } }];

