// Map ids back to keywords, drop invented ids, keep each keyword in one cluster, rank clusters
const src = $('Clean and count keywords').all();
return $input.all().map((item, i) => {
  const P = src[i].json, o = item.json.output || {};
  const byId = new Map(P.keywords.map(k => [k.id, k]));
  const used = new Set(), clusters = [];
  for (const c of (o.clusters || [])) {
    const ids = [...new Set((c.keyword_ids || []).map(Number))].filter(id => byId.has(id) && !used.has(id));
    if (!ids.length) continue;
    ids.forEach(id => used.add(id));
    let pillar = Number(c.pillar_id);
    if (!ids.includes(pillar)) pillar = ids.slice().sort((a, b) => byId.get(b).hits - byId.get(a).hits || byId.get(a).keyword.length - byId.get(b).keyword.length)[0];
    const members = ids.map(id => byId.get(id));
    const hits = members.reduce((a, k) => a + k.hits, 0);
    const intent = ['informational', 'commercial', 'transactional', 'navigational'].includes(c.intent) ? c.intent : 'informational';
    const priority = Math.min(5, Math.max(1, Math.round(Number(c.priority) || 3)));
    const gap = false, covered = false;
    clusters.push({ cluster: String(c.name || byId.get(pillar).keyword).slice(0, 80), pillar_keyword: byId.get(pillar).keyword, intent,
      funnel: c.funnel || '', content_type: c.content_type || '', priority, title: c.title || byId.get(pillar).keyword,
      keywords: members.map(k => k.keyword), questions: members.filter(k => k.is_question).map(k => k.keyword),
      keyword_count: members.length, total_hits: hits, gap, covered,
      score: priority * 10 + Math.min(hits, 40) + (['commercial', 'transactional'].includes(intent) ? 5 : 0) + (gap ? 8 : 0) - (covered ? 15 : 0) });
  }
  clusters.sort((a, b) => b.score - a.score);
  const ignored = new Set((o.ignored_ids || []).map(Number));
  const of = {};
  clusters.forEach(c => c.keywords.forEach(k => { of[k] = c; }));
  const keywords = P.keywords.map(k => ({ ...k, cluster: of[k.keyword] ? of[k.keyword].cluster : ignored.has(k.id) ? '(off-topic)' : '(unclustered)',
    intent: of[k.keyword] ? of[k.keyword].intent : k.intent_hint }));
  return { json: { ...P, clusters, keywords, keyword_list: undefined, unclustered: keywords.filter(k => k.cluster === '(unclustered)').length, ignored: ignored.size } };
});

// One row per keyword for the Keywords tab (upserted by keyword_key, so re-runs update last_seen)
const out = [];
for (const P of $('Validate clusters').all().map(i => i.json))
  for (const k of P.keywords) out.push({ json: { keyword_key: k.keyword_key, project: P.project, keyword: k.keyword, seed: k.seed,
    hits: k.hits, words: k.words, is_question: k.is_question ? 'yes' : 'no', intent: k.intent, cluster: k.cluster, last_seen: k.last_seen } });
return out;

const s = $('Set planner settings').first().json;
const start = (() => { const d = s.start_date ? DateTime.fromISO(String(s.start_date)) : null;
  if (d && d.isValid) return d; const t = $today; return t.plus({ days: ((8 - t.weekday) % 7) || 7 }); })();  // next Monday
const OFF = { 1: [0], 2: [0, 3], 3: [0, 2, 4], 4: [0, 1, 3, 4], 5: [0, 1, 2, 3, 4] };
const dateFor = (n, perWeek) => { const offs = OFF[Math.min(Math.max(perWeek, 1), 5)]; return start.plus({ weeks: Math.floor(n / offs.length), days: offs[n % offs.length] }).toFormat('yyyy-MM-dd'); };
// Content calendar: the highest-ranked clusters, one article each, spread over the next weeks
const perWeek = Number(s.posts_per_week) || 2, weeks = Number(s.weeks) || 4;
const out = [];
for (const P of $('Validate clusters').all().map(i => i.json))
  P.clusters.slice(0, perWeek * weeks).forEach((c, n) => out.push({ json: {
    slot_key: `${P.project}|${c.pillar_keyword}`, project: P.project, publish_date: dateFor(n, perWeek), title: c.title,
    primary_keyword: c.pillar_keyword, secondary_keywords: c.keywords.filter(k => k !== c.pillar_keyword).slice(0, 10).join(', '),
    questions: c.questions.slice(0, 6).join(' | '), cluster: c.cluster, intent: c.intent, funnel: c.funnel, content_type: c.content_type,
    priority: c.priority, status: 'planned' } }));
return out;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Results page
const P = $('Validate clusters').first().json;
const cal = $('Build content calendar').all().map(i => i.json);
const rows = P.clusters.slice(0, 12).map(c => `<tr><td><b>${esc(c.cluster)}</b><br><small>${esc(c.keywords.slice(0, 6).join(', '))}</small></td><td>${esc(c.intent)}</td><td>${c.keyword_count}</td><td>${c.priority}</td></tr>`).join('');
const plan = cal.map(c => `<li>${esc(c.publish_date)}: <b>${esc(c.title)}</b> (${esc(c.primary_keyword)})</li>`).join('');
return [{ json: { html: `<p>${P.queries} Autocomplete queries${P.failed_queries ? ` (${P.failed_queries} failed)` : ''} &rarr; <b>${P.keyword_count}</b> keywords &rarr; <b>${P.clusters.length}</b> clusters. Saved to your Keywords and Calendar tabs.</p>
<h3>Top clusters</h3><table border="1" cellpadding="6" style="border-collapse:collapse;font-size:13px"><tr><th>Cluster</th><th>Intent</th><th>Keywords</th><th>Priority</th></tr>${rows}</table>
<h3>Content calendar</h3><ol>${plan}</ol>` } }];
